import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { palettes } from "@newbrush/tokens/seeds";
import { customThemeCss } from "@newbrush/tokens/theme";
import { expect, test } from "@playwright/test";
import { expectNoAxeViolations } from "../harness/fixtures.ts";

// T065 — examples/brand-theme: two named themes generated by `nb theme create` from one seed, no build step.
const example = (file: string) => new URL(`../../../examples/brand-theme/${file}`, import.meta.url);
const SEED = "#e11d48";
const brand = palettes({ brand: SEED }).brand ?? [];

test("the checked-in themes are what `nb theme create` generates today", () => {
  const tokensCss = readFileSync(
    createRequire(import.meta.url).resolve("@newbrush/tokens/tokens.css"),
    "utf8",
  );
  for (const [name, from, flags] of [
    ["acme", "light", ""],
    ["acme-dark", "dark", " --from dark"],
  ] as const) {
    const expected = customThemeCss({
      name,
      from,
      seeds: { brand: SEED },
      tokensCss,
      command: `nb theme create ${name} --seed ${SEED}${flags}`,
    });
    expect(
      readFileSync(example(`themes/${name}.css`), "utf8"),
      `${name}.css is stale: regenerate it`,
    ).toBe(expected);
  }
});

test("the page uses acme, the dark island acme-dark, both from the seed, accessibly", async ({
  page,
}) => {
  const errors: string[] = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto(example("index.html").href);
  const prop = (sel: string, name: string) =>
    page
      .locator(sel)
      .first()
      .evaluate((el, n) => getComputedStyle(el).getPropertyValue(n).trim(), name);
  // the generated brand steps, not the framework's default blue (hue 255)
  expect(await prop("html", "--nb-color-brand-600")).toBe(brand[6]?.value);
  expect(await prop("html", "--nb-scheme")).toBe("light");
  expect(await prop("#pricing", "--nb-scheme")).toBe("dark");
  // primary buttons: light accent is brand.600, dark accent brand.400
  const bg = (sel: string) =>
    page.locator(sel).evaluate((el) => getComputedStyle(el).backgroundColor);
  const expected = (color: string) =>
    page.evaluate((c) => {
      const probe = document.createElement("i");
      probe.style.backgroundColor = c;
      document.body.append(probe);
      const value = getComputedStyle(probe).backgroundColor;
      probe.remove();
      return value;
    }, color);
  expect(await bg("#top > section:first-child .nb-btn--primary")).toBe(
    await expected(brand[6]?.value ?? ""),
  );
  expect(await bg("#pricing .nb-btn--primary")).toBe(await expected(brand[4]?.value ?? ""));
  expect(errors).toEqual([]);
  await expectNoAxeViolations(page);
});
